create or replace function public.map_network_nearby_v1(p_lat double precision,p_lng double precision,p_radius_m integer default 30000,p_limit integer default 250,p_category text default null,p_search text default null,p_amenity_names text[] default '{}') returns table(location_id uuid,place_id uuid,name text,category text,address text,city text,state text,postal_code text,latitude double precision,longitude double precision,distance_meters double precision,source text,source_dataset text,source_external_id text,is_verified boolean,rating numeric,review_count integer,cleanliness_pct numeric,verification_confidence numeric,amenities jsonb,fixtures jsonb,brand text,operator_name text,osm_tags jsonb) language sql stable security definer set search_path=public,auth,extensions,pg_temp as $$ with base as (select l.id,p.id as place_id,l.place_type,l.name,l.address,l.city,l.state,l.postal_code,l.latitude,l.longitude,l.source,l.source_dataset,l.source_external_id,l.source_metadata,l.rating as l_rating,l.review_count as l_review_count,l.cleanliness_pct,l.verification_confidence,p.category as p_category,p.rating as p_rating,p.review_count as p_review_count,p.is_verified as p_is_verified,p.name as place_name,coalesce(l.source_metadata->>'brand',l.source_metadata->>'brand_name') as brand_name,coalesce(l.source_metadata->>'operator',l.source_metadata->>'operator_name') as operator_name,6371000.0*2*asin(sqrt(power(sin(radians(l.latitude-p_lat)/2),2)+cos(radians(p_lat))*cos(radians(l.latitude))*power(sin(radians(l.longitude-p_lng)/2),2))) as dist,(lower(coalesce(l.bathroom_verification_status,'')) in ('has_bathroom','verified') or lower(coalesce(l.place_type,'')) in ('restroom','bathroom','toilet') or lower(coalesce(p.category,'')) in ('restroom','bathroom','toilet') or lower(coalesce(l.source_metadata->>'amenity','')) in ('toilets','restroom','bathroom') or lower(coalesce(l.source_metadata->>'toilets','')) in ('yes','public','customers') or lower(coalesce(l.source_metadata->>'restroom','')) in ('yes','public','customers') or lower(coalesce(l.source_metadata->>'bathroom','')) in ('yes','public','customers') or coalesce(l.source_metadata->'osm_tags'->>'amenity','') ilike 'toilet%') as bathroom_signal from public.locations l left join public.places p on p.location_id=l.id and p.is_active=true where l.is_active=true and l.latitude is not null and l.longitude is not null and l.latitude between p_lat-(p_radius_m/111320.0) and p_lat+(p_radius_m/111320.0) and l.longitude between p_lng-(p_radius_m/(111320.0*greatest(cos(radians(p_lat)),0.2))) and p_lng+(p_radius_m/(111320.0*greatest(cos(radians(p_lat)),0.2))) and (p_category is null or lower(p_category)='all' or lower(p_category)=lower(coalesce(p.category,l.place_type,'')) or (lower(p_category)='brand' and coalesce(l.source_metadata->>'brand',l.source_metadata->>'brand_name') is not null) or (lower(p_category)='restroom' and (lower(coalesce(l.bathroom_verification_status,'')) in ('has_bathroom','verified') or lower(coalesce(l.place_type,'')) in ('restroom','bathroom','toilet') or lower(coalesce(p.category,'')) in ('restroom','bathroom','toilet') or lower(coalesce(l.source_metadata->>'amenity','')) in ('toilets','restroom','bathroom') or lower(coalesce(l.source_metadata->>'toilets','')) in ('yes','public','customers') or lower(coalesce(l.source_metadata->>'restroom','')) in ('yes','public','customers') or lower(coalesce(l.source_metadata->>'bathroom','')) in ('yes','public','customers') or coalesce(l.source_metadata->'osm_tags'->>'amenity','') ilike 'toilet%')) or (lower(p_category)='restaurant' and lower(coalesce(p.category,l.place_type,'')) similar to '%(restaurant|food|fast_food)%') or (lower(p_category)='cafe' and lower(coalesce(p.category,l.place_type,'')) similar to '%(cafe|coffee)%') or (lower(p_category)='gas_station' and lower(coalesce(p.category,l.place_type,'')) similar to '%(gas|fuel)%') or (lower(p_category)='shopping' and lower(coalesce(p.category,l.place_type,'')) similar to '%(shop|retail|supermarket|mall)%') or (lower(p_category)='government' and lower(coalesce(p.category,l.place_type,'')) like '%government%') or (lower(p_category)='park' and lower(coalesce(p.category,l.place_type,'')) similar to '%(park|recreation)%') or (lower(p_category)='health' and lower(coalesce(p.category,l.place_type,'')) similar to '%(hospital|clinic|health|medical|pharmacy)%') or (lower(p_category)='public_safety' and lower(coalesce(p.category,l.place_type,'')) similar to '%(police|fire|emergency|public_safety|public safety)%') or (lower(p_category)='cooling_center' and lower(coalesce(p.category,l.place_type,'')) similar to '%(cooling|heat relief|warming)%')) and (nullif(trim(p_search),'') is null or coalesce(l.name,'') ilike '%'||p_search||'%' or coalesce(p.name,'') ilike '%'||p_search||'%' or coalesce(l.address,'') ilike '%'||p_search||'%' or coalesce(l.city,'') ilike '%'||p_search||'%' or coalesce(l.state,'') ilike '%'||p_search||'%' or coalesce(l.postal_code,'') ilike '%'||p_search||'%' or coalesce(l.source_metadata->>'brand','') ilike '%'||p_search||'%' or coalesce(l.source_metadata->>'brand_name','') ilike '%'||p_search||'%' or coalesce(l.source_metadata->>'operator','') ilike '%'||p_search||'%' or coalesce(l.source_metadata->>'operator_name','') ilike '%'||p_search||'%') and (coalesce(cardinality(p_amenity_names),0)=0 or exists (select 1 from public.location_amenities la join public.amenities aa on aa.id=la.amenity_id where la.location_id=l.id and aa.name=any(p_amenity_names))) ), ranked as (select * from base where dist<=p_radius_m order by case when lower(coalesce(p_category,''))='restroom' then not bathroom_signal else false end,dist limit greatest(1,least(p_limit,500))), amen as (select la.location_id,jsonb_agg(distinct jsonb_build_object('name',a.name,'category',a.category)) items from public.location_amenities la join public.amenities a on a.id=la.amenity_id group by la.location_id), fx as (select lf.location_id,jsonb_build_object('stalls',lf.stalls,'urinals',lf.urinals,'sinks',lf.sinks,'hand_dryers',lf.hand_dryers,'changing_tables',lf.changing_tables,'showers',lf.showers) items from public.location_fixtures lf) select r.id,r.place_id,coalesce(r.place_name,r.name),case when lower(coalesce(p_category,''))='restroom' then 'restroom' when lower(coalesce(p_category,''))='park' then 'park' when lower(coalesce(p_category,''))='health' then 'health' when lower(coalesce(p_category,''))='public_safety' then 'public_safety' when lower(coalesce(p_category,''))='cooling_center' then 'cooling_center' when r.brand_name is not null and lower(coalesce(r.p_category,r.place_type,''))='service' then 'brand' else coalesce(r.p_category,r.place_type,'service') end,r.address,r.city,r.state,r.postal_code,r.latitude,r.longitude,r.dist,r.source,r.source_dataset,r.source_external_id,coalesce(r.p_is_verified,false),coalesce(r.p_rating,r.l_rating,0),coalesce(r.p_review_count,r.l_review_count,0),r.cleanliness_pct,r.verification_confidence,coalesce(a.items,'[]'::jsonb),coalesce(f.items,'{}'::jsonb),r.brand_name,r.operator_name,coalesce(r.source_metadata->'osm_tags','{}'::jsonb) from ranked r left join amen a on a.location_id=r.id left join fx f on f.location_id=r.id order by r.dist; $$; grant execute on function public.map_network_nearby_v1(double precision,double precision,integer,integer,text,text,text[]) to anon,authenticated;
